--

DROP TABLE IF EXISTS `returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `returns` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `return_number` varchar(50) NOT NULL,
  `original_sale_id` int(11) DEFAULT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `return_type` enum('Devolucao','Troca','Garantia') NOT NULL,
  `return_reason` enum('Produto Defeituoso','Produto Errado','Nao Gostou','Validade Proxima','Arrependimento','Outro') NOT NULL,
  `reason_description` text DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `refund_method` enum('Dinheiro','Cartao','Vale','Troca Produto') NOT NULL,
  `status` enum('Pendente','Aprovada','Recusada','Processada') DEFAULT 'Pendente',
  `processed_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `return_date` datetime DEFAULT current_timestamp(),
  `processed_at` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `return_number` (`return_number`),
  KEY `original_sale_id` (`original_sale_id`),
  KEY `processed_by` (`processed_by`),
  KEY `idx_return_date` (`return_date`),
  KEY `idx_status` (`status`),
  KEY `idx_customer` (`customer_id`),
  CONSTRAINT `returns_ibfk_1` FOREIGN KEY (`original_sale_id`) REFERENCES `sales` (`id`),
  CONSTRAINT `returns_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `returns_ibfk_3` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
